def t(th, en): return f'<span lang="th">{th}</span><span lang="en">{en}</span>'
def icon(name='arrow'):
    paths = {
        'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
        'up':'<path d="M6 18 18 6M6 6h12v12"/>',
        'pin':'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
        'bolt':'<path d="m14 2-9 12h7l-2 8 9-12h-7l2-8Z"/>',
        'plug':'<path d="M8 2v5m8-5v5M5 7h14v4a7 7 0 0 1-14 0V7Zm7 11v4"/>',
        'leaf':'<path d="M20 3C8 2 3 7 5 14s13 7 15-11Z"/><path d="M3 22 16 9"/>',
        'check':'<path d="m5 12 4 4L19 6"/>',
        'phone':'<path d="m5 3 4 1 1 5-3 2c2 4 3 5 6 6l2-3 5 1 1 4c-1 4-6 3-11 0C5 16 1 8 3 4l2-1Z"/>',
        'menu':'<path d="M5 8h14M5 16h14"/>',
        'close':'<path d="m6 6 12 12M6 18 18 6"/>',
        'clock':'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
    }
    return f'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[name]}</svg>'

