PAGES=[]
def shell(title,desc,active,body,canon='/'):
    quickbar=f'<nav class="mobile-quickbar" aria-label="ติดต่อสถานี / Station quick actions"><a href="{MAP}" target="_blank" rel="noopener noreferrer">{icon("pin")}{t("นำทางมายังสถานี","Get directions")}</a><a href="tel:0810024867">{icon("phone")}{t("โทรสอบถามทีมงาน","Call the team")}</a></nav>'
    return f'''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · BCSM 1989</title><meta name="description" content="{html.escape(desc)}"><meta name="theme-color" content="#f7f5ef"><meta name="robots" content="index,follow"><link rel="canonical" href="https://bcsm1989.com{canon}"><meta property="og:url" content="https://bcsm1989.com{canon}"><meta property="og:title" content="{html.escape(title)} · BCSM 1989"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><link rel="icon" type="image/png" href="/assets/logo-earth.png"><link rel="stylesheet" href="/style.css"><script src="/app.js"></script></head><body>{header(active)}<main id="main">{body}</main>{footer()}{quickbar}</body></html>'''
def save(page,title,desc,body,active=None):
    target=DIST / page / 'index.html' if page else DIST/'index.html'
    target.parent.mkdir(parents=True,exist_ok=True)
    canon='/' if not page else f'/{page}/'
    PAGES.append(canon)
    target.write_text(shell(title,desc,active or page,body,canon),encoding='utf-8')
