# Keep the full Thai and English privacy and account deletion bodies exactly as published.
for slug,title in [('privacy','นโยบายความเป็นส่วนตัว'),('delete-account','ขอลบบัญชีและข้อมูล')]:
    original=(ROOT/'source-original'/f'{slug}.html').read_text()
    body=re.search(r'<main><div class="wrap">(.*?)</div></main>',original,re.S).group(1)
    content=f'<div class="container"><article class="prose">{body}</article></div>'
    save(slug,title,f'{title} — บริษัท บีซีเอสเอ็ม 1989 จำกัด',content)

